const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0060, 40.7128]); // New York City (approx. center)
  const startDate = '2002-08-14';
  const endDate = '2002-08-15'; // For daily data, cover the single day

  // Define a buffer around NYC for analysis
  const analysisGeometry = nyc.buffer(10000); // 10km buffer

  // 2. Data Acquisition & Check
  // MODIS LST (Terra)
  let mod11a1 = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(analysisGeometry);

  // MODIS NDVI (Terra)
  let mod13a1 = ee.ImageCollection('MODIS/061/MOD13A1')
    .filterDate(startDate, endDate) // MOD13A1 is 16-day, so this will get the composite covering the date
    .filterBounds(analysisGeometry);

  const mod11a1Size = await mod11a1.size().getInfo();
  const mod13a1Size = await mod13a1.size().getInfo();

  if (mod11a1Size === 0 || mod13a1Size === 0) {
    console.log(`LST Images: ${mod11a1Size}, NDVI Images: ${mod13a1Size}`);
    console.log("C1");
    return;
  }

  // Get the single image for LST and NDVI
  const lstImage = ee.Image(mod11a1.first());
  const ndviImage = ee.Image(mod13a1.first());

  // Cloud and Quality Masking for LST
  function maskLST(image) {
    const qa = image.select('QC_Day');
    // Bits 0-1: LST quality (00 = good, 01 = good but not ideal)
    // Bits 2-3: Cloud state (00 = clear, 01 = cloudy, 10 = mixed, 11 = not set)
    const goodQuality = qa.bitwiseAnd(ee.Number(3)).eq(0); // LST produced, good quality
    const clearSky = qa.bitwiseAnd(ee.Number(12)).eq(0); // Clear sky conditions

    // Mask out water (LST_Day_1km fill value for water is 0)
    const lst = image.select('LST_Day_1km').neq(0);

    return image.updateMask(goodQuality.and(clearSky).and(lst));
  }

  // Cloud and Quality Masking for NDVI
  function maskNDVI(image) {
    const qa = image.select('QA');
    // Bits 0-1: MODLAND_QA (00 = good, 01 = marginal, 10 = snow/ice, 11 = cloudy)
    const goodQuality = qa.bitwiseAnd(ee.Number(3)).eq(0); // Good data

    return image.updateMask(goodQuality);
  }

  const maskedLST = maskLST(lstImage);
  const maskedNDVI = maskNDVI(ndviImage);

  // Select LST_Day_1km and convert to Celsius
  // LST is in Kelvin * 0.02. Convert to Celsius: (LST * 0.02) - 273.15
  const lstCelsius = maskedLST.select('LST_Day_1km').multiply(0.02).subtract(273.15).rename('LST');

  // Select NDVI and scale it
  // NDVI is scaled by 10000, so divide by 10000
  const scaledNDVI = maskedNDVI.select('NDVI').divide(10000).rename('NDVI');

  // Combine LST and NDVI into a single image
  const combinedImage = lstCelsius.addBands(scaledNDVI);

  // Check valid pixel count after masking
  const pixelCount = await combinedImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: analysisGeometry,
    scale: 1000, // MODIS resolution is 1km
    maxPixels: 1e9
  }).getInfo();

  const lstPixels = pixelCount.LST;
  const ndviPixels = pixelCount.NDVI;

  if (lstPixels === 0 || ndviPixels === 0 || lstPixels === undefined || ndviPixels === undefined) {
    console.log(`LST Valid Pixels: ${lstPixels}, NDVI Valid Pixels: ${ndviPixels}`);
    console.log("C2");
    return;
  }

  // Calculate Pearson's correlation between LST and NDVI in non-water areas
  const correlation = await combinedImage.select(['LST', 'NDVI'])
    .reduceRegion({
      reducer: ee.Reducer.pearsonsCorrelation(),
      geometry: analysisGeometry,
      scale: 1000,
      maxPixels: 1e9,
      tileScale: 16 // Use tileScale for large computations
    }).getInfo();

  const rValue = correlation.correlation;

  if (rValue === null || isNaN(rValue)) {
    console.log("Correlation calculation failed: Result is null or NaN.");
    console.log("C3");
    return;
  }

  // Interpretation:
  // A negative correlation coefficient means that as NDVI (vegetation density) increases,
  // LST (surface temperature) tends to decrease.

  console.log(`LST Images: ${mod11a1Size}, NDVI Images: ${mod13a1Size}`);
  console.log(`Valid LST Pixels: ${lstPixels}, Valid NDVI Pixels: ${ndviPixels}`);
  console.log(`Pearson's Correlation (LST vs NDVI): ${rValue.toFixed(4)}`);

  if (rValue < -0.1) { // A negative correlation stronger than -0.1 indicates a decreasing trend
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
